//! Scenario I (spec 11): nesting, the `*Fields` split borrow, and a
//! constructor-form edge that moves a non-`Clone` buffer into `Failed`.
//!
//! The same cases (`i_media_player/cases.rs`) run against the hand-written
//! machine and against the machine generated by `#[machine]` (milestone M3).
//! The only observable difference: the hand-written edges log a line when a
//! constructor runs (`construct Failed`); a generated constructor is the
//! user's closure and has no `Cx`, so it logs nothing.

mod hand_written {
    use estado_examples::i_media_player as scenario;

    const LOGS_CONSTRUCTORS: bool = true;

    include!("i_media_player/cases.rs");
}

mod with_macro {
    use estado_examples::i_media_player_macro as scenario;

    const LOGS_CONSTRUCTORS: bool = false;

    include!("i_media_player/cases.rs");
}
